def solve(data):
    MOD=998244353
    n=int(data[0]); A=list(map(int,data[1:1+n]))
    M=max(A)
    phi=list(range(M+1))
    for p in range(2,M+1):
        if phi[p]==p:
            for q in range(p,M+1,p):
                phi[q]-=phi[q]//p
    present=set(A)
    divs={v:[] for v in present}
    for d in range(1,M+1):
        for v in range(d,M+1,d):
            if v in divs: divs[v].append(d)
