    for v in present:
        D=np.array(divs[v],dtype=np.int64)
        P=np.array([phi[d] for d in divs[v]],dtype=np.int64)
        cache[v]=(D,P)
    U=np.zeros(M+1,dtype=np.int64)
    out=[]; ans=0; w=1
