from itertools import permutations
def lis(seq, inc=True):
    if not seq: return 0
    best=[1]*len(seq)
    for i in range(len(seq)):
        for j in range(i):
            if (seq[j]<seq[i] if inc else seq[j]>seq[i]) and best[j]+1>best[i]:
                best[i]=best[j]+1
    return max(best)
def main():
    A,B,M=map(int,sys.stdin.read().split())
    N=A*B-1
    cnt=0
    for p in permutations(range(1,N+1)):
        if lis(p,True)!=A or lis(p,False)!=B: continue
        ok=False
        for n in range(0,N+1):
            small=[x for x in p if x<=n]
            large=[x for x in p if x>n]
            if lis(small,True)<A and lis(large,False)<B:
                ok=True;break
        if ok: cnt+=1
    print(cnt%M)
