import sys
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        # ops[c]: number of operations to reach 1 from c (c >= 1)
        ops = [0] * (L + 2)
        for c in range(2, L + 2):
            ops[c] = 1 + ops[bin(c).count('1')]
        # binomials
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
        # cnt[c] = number of x in [0, n-1] with popcount c
        cnt = [0] * (L + 2)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                m = L - 1 - i
                # place 0 here, choose remaining bits freely
                for c in range(ones, ones + m + 1):
                    if c <= L + 1:
                        cnt[c] = (cnt[c] + C[m][c - ones]) % MOD
                ones += 1
        ans = 0
        for c in range(1, L + 1):
            if ops[c] + 1 <= k:
                ans = (ans + cnt[c]) % MOD
        return ans

