import random, itertools
def fast(n,X,T):
    U=[t[0] for t in T]; D=[t[1] for t in T]
    S=sum(U)+sum(D)
    def feas(H):
        L=R=None
        for i in range(n):
            lo=max(0,H-D[i]); hi=min(U[i],H)
            if lo>hi: return False
            if i==0: L,R=lo,hi
            else:
                nl=max(lo,L-X); nr=min(hi,R+X)
                if nl>nr: return False
                L,R=nl,nr
        return True
    best=None
    for H in range(0,min(U[i]+D[i] for i in range(n))+1):
        if feas(H): best=H
    return S-n*best
def brute(n,X,T):
    best=None
    for H in range(0,max(U+D for U,D in T)+2):
        # enumerate u_i in [0,min(U,H)] with D'=H-u in [0,D]
        opts=[]
        for U,D in T:
            opts.append([u for u in range(0,min(U,H)+1) if 0<=H-u<=D])
        for ch in itertools.product(*opts):
            if all(abs(ch[i]-ch[i+1])<=X for i in range(n-1)):
                cost=sum(T[i][0]+T[i][1]-ch[i]-(H-ch[i]) for i in range(n))
                if best is None or cost<best: best=cost
    return best
