import sys, heapq
def main():
    d = sys.stdin.buffer.read().split()
    H, W, X = int(d[0]), int(d[1]), int(d[2])
    P, Q = int(d[3]) - 1, int(d[4]) - 1
    S = [int(v) for v in d[5:5 + H * W]]
    inside = bytearray(H * W)
    start = P * W + Q
    total = S[start]
    inside[start] = 1
    heap = []
    def push_nb(c):
        r, col = divmod(c, W)
        if r > 0 and not inside[c - W]: heapq.heappush(heap, (S[c - W], c - W))
        if r < H - 1 and not inside[c + W]: heapq.heappush(heap, (S[c + W], c + W))
        if col > 0 and not inside[c - 1]: heapq.heappush(heap, (S[c - 1], c - 1))
        if col < W - 1 and not inside[c + 1]: heapq.heappush(heap, (S[c + 1], c + 1))
    push_nb(start)
    while heap:
        s, c = heap[0]
        if X * s >= total:
            break
        heapq.heappop(heap)
        if inside[c]:
            continue
        inside[c] = 1
        total += s
        push_nb(c)
    print(total)
