import sys, time
def solve(N, A):
    L = 100
    LIM = 1 << 100
    cnt = []
    masks = []
    for v in range(L):
        m = (1 << (v + 2)) - 1
        masks.append(m)
        d = {}
        for a in A:
            x = a & m
            d[x] = d.get(x, 0) + 1
        cnt.append(d)
    pw = [1 << v for v in range(L)]
    best = 0
    seen = set()
    AN = A[-1]
    for u in range(L):
        M = 1 << (u + 2)
        mask = M - 1
        for a in A:
            r = (pw[u] - a) & mask
            if r == 0:
                r = M
            if r in seen and False:
                continue
            if r < 1 or r + AN > LIM - 1:
                continue
            s = 0
            for v in range(L):
                s += cnt[v].get((pw[v] - r) & masks[v], 0)
            if s > best:
                best = s
    return best

