import random
from collections import deque
def sol(N,M,A,B):
    c=[0]*N
    for i in range(N-1):
        s = A[i]>A[i+1]
        d = B[i]-B[i+1]
        if s: j = 0 if d>0 else 1
        else: j = 0 if d<0 else -1
        c[i+1]=c[i]-j
    v=sorted(A[i]-B[i]-c[i]*M for i in range(N))
    med=v[N//2]
    t0=med//M
    best=None
    for t in (t0-1,t0,t0+1,t0+2):
        cost=sum(abs(B[i]+(t+c[i])*M-A[i]) for i in range(N))
        if best is None or cost<best: best=cost
    return best
def brute(N,M,A,B):
    A=tuple(A);B=tuple(B)
    dist={A:0};q=deque([A])
    while q:
        s=q.popleft()
        if s==B: return dist[s]
        for i in range(N):
            for d in (1,-1):
                t=list(s); t[i]=(t[i]+d)%M
                if i>0 and t[i]==t[i-1]: continue
                if i<N-1 and t[i]==t[i+1]: continue
                t=tuple(t)
                if t not in dist:
                    dist[t]=dist[s]+1; q.append(t)
    return -1
