from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @functools.lru_cache(maxsize=None)
        def f(o, e, p):
            if o == 0 and e == 0:
                return 1
            if p == 0:
                return o * f(o - 1, e, 1) if o > 0 else 0
            return e * f(o, e - 1, 0) if e > 0 else 0
        odds = (n + 1) // 2
        evens = n // 2
        total = 0
        for x in range(1, n + 1):
            if x % 2 == 1:
                total += f(odds - 1, evens, 1)
            else:
                total += f(odds, evens - 1, 0)
        if k > total:
            return []
        rem = set(range(1, n + 1))
        res = []
        prev = None
        for _ in range(n):
            o = sum(1 for v in rem if v % 2 == 1)
            e = len(rem) - o
            for x in sorted(rem):
                if prev is not None and (x % 2) == (prev % 2):
                    continue
                if x % 2 == 1:
                    c = f(o - 1, e, 1)
                else:
                    c = f(o, e - 1, 0)
                if k <= c:
                    res.append(x)
                    rem.remove(x)
                    prev = x
                    break
                k -= c
        return res

