class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        p = [1 % k] * (n + 1)
        for j in range(1, n + 1):
            p[j] = p[j - 1] * 10 % k
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w[i] = p[i]
            else:
                w[i] = (p[i] + p[j]) % k
        R = [None] * (h + 1)
        base = [False] * k
        base[0] = True
        R[h] = base
        for i in range(h - 1, -1, -1):
            lo = 1 if i == 0 else 0
            nxt = R[i + 1]
            cur = [False] * k
            wi = w[i]
            for d in range(lo, 10):
                s = d * wi % k
                for r in range(k):
                    if nxt[r]:
                        cur[(s + r) % k] = True
            R[i] = cur
        if not R[0][0]:
            return ""
        res = [0] * h
        c = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nc = (c + d * w[i]) % k
                if R[i + 1][(-nc) % k]:
                    res[i] = d
                    c = nc
                    break
        left = [chr(48 + x) for x in res]
        if n % 2:
            s = left + left[-2::-1]
        else:
            s = left + left[::-1]
        return "".join(s)

