from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        B1 = [0]*(n+2); B2 = [0]*(n+2)
        def upd(B, i, v):
            i += 1
            while i <= n:
                B[i] += v; i += i & -i
        def qry(B, i):
            s = 0; i += 1
            while i > 0:
                s += B[i]; i -= i & -i
            return s
        def range_add(l, r, v):
            upd(B1, l, v); upd(B1, r+1, -v)
            upd(B2, l, v*(l-1)); upd(B2, r+1, -v*r)
        def pref(i):
            if i < 0: return 0
            return qry(B1, i)*i - qry(B2, i)
        stack = []
        ans = 0
        r = n-1
        for l in range(n-1, -1, -1):
            v = nums[l]
            end = l
            while stack and stack[-1][2] < v:
                s, e, val = stack.pop()
                range_add(s, e, v - val)
                end = e
            stack.append((l, end, v))
            base = pref(l-1)
            while pref(r) - base > k:
                r -= 1
            ans += r - l + 1
        return ans

