    def maximizeSumOfWeights(self, edges, k):
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        parent = [-1] * n; visited = [False] * n; visited[0] = True; order = []; stack = [0]
        while stack:
