    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1])
    N=H*W
    F=[int(x) for x in data[2:2+N]]
    p=2+N
    edges=[]
    for i in range(H):
        for j in range(W):
            u=i*W+j
            if j+1<W:
                v=u+1; edges.append((min(F[u],F[v]),u,v))
            if i+1<H:
                v=u+W; edges.append((min(F[u],F[v]),u,v))
    edges.sort(key=lambda e:-e[0])
    par=list(range(N)); sz=[1]*N
    INF=1<<60
    tm=[INF]*N
    wt=[0]*len(edges)
    def find(x):
        while par[x]!=x:
            x=par[x]
        return x
    for k,(w,u,v) in enumerate(edges):
        wt[k]=w
        ru=find(u); rv=find(v)
        if ru!=rv:
            if sz[ru]<sz[rv]: ru,rv=rv,ru
            par[rv]=ru; sz[ru]+=sz[rv]; tm[rv]=k
    Q=int(data[p]); p+=1
    out=[]
    for _ in range(Q):
        A,B_,Y,C,D,Z=(int(x) for x in data[p:p+6]); p+=6
        u=(A-1)*W+(B_-1); v=(C-1)*W+(D-1)
        if u==v:
            B=F[u]
        else:
            last=-1
            while u!=v:
                if tm[u]>tm[v]:
