import sys, bisect

def _occ(x, s):
    n = len(s)
    m = len(x)
    if m == 0:
        return list(range(n + 1))
    t = x + '\x00' + s
    L = len(t)
    z = [0] * L
    l = r = 0
    for i in range(1, L):
        if i < r:
            zi = min(r - i, z[i - l])
        else:
            zi = 0
        while i + zi < L and t[zi] == t[i + zi]:
            zi += 1
        z[i] = zi
        if i + zi > r:
            l, r = i, i + zi
    res = []
    off = m + 1
    for i in range(n):
        if z[off + i] >= m:
            res.append(i)
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        a = p[:i1]
        b = p[i1 + 1:i2]
        c = p[i2 + 1:]
        A = _occ(a, s)
        B = _occ(b, s)
        C = _occ(c, s)
        if not A or not B or not C:
            return -1
        la, lb, lc = len(a), len(b), len(c)
        best = None
        for j in B:
            idx = bisect.bisect_right(A, j - la) - 1
            if idx < 0:
                continue
            i = A[idx]
            kidx = bisect.bisect_left(C, j + lb)
            if kidx >= len(C):
                continue
            k = C[kidx]
            v = k + lc - i
