def feasible_T(P,T,Tg):
    m=len(P); k=len(Tg)
    d=Tg[0]-P[0]
    if T+d<0 or d>T: return False
    xs=frozenset(range(max(0,d), min(T,(T+d)//2)+1))
    if not xs: return False
    states={(0,d):xs}
    for kk in range(1,m):
        ns={}
        for (t,dprev),X in states.items():
            for nt in (t,t+1):
                if nt>=k: continue
                dn=Tg[nt]-P[kk]
                if dn>dprev or dn<-T or dn>T: continue
                nx=set()
                for Xn in range(max(0,dn), min(T,(T+dn)//2)+1):
                    if any((Xk>=Xn) and (Xk<=Xn+dprev-dn) and (Xk+Xn>=T+dn) for Xk in X):
                        nx.add(Xn)
                if nx:
                    key=(nt,dn)
                    ns[key]=ns.get(key,frozenset())|frozenset(nx)
        states=ns
        if not states: return False
    return any(t==k-1 for (t,_) in states)
