def solve(N):
    M = math.isqrt(N)
    L = max(M, 2)
    s = bytearray([1]) * (L + 1)
    s[0] = s[1] = 0
    for i in range(2, math.isqrt(L) + 1):
        if s[i]:
            s[i*i::i] = bytearray(len(range(i*i, L+1, i)))
    pi = list(itertools.accumulate(s))
    primes = [i for i in range(2, L + 1) if s[i]]
    ans = sum(1 for p in primes if p**8 <= N)
