        n = len(nums)
        reach = [1] * n  # bit s set => sum s achievable at index i
        def done():
            for i in range(n):
                if not (reach[i] >> nums[i]) & 1:
                    return False
            return True
        if done():
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                m = (1 << (nums[i] + 1)) - 1
                reach[i] = (reach[i] | (reach[i] << v)) & m
            if done():
                return k + 1
        return -1

