import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L = len(str(n))
        N = 10 ** L
        def isp(x):
            if x < 2:
                return False
            i = 2
            while i * i <= x:
                if x % i == 0:
                    return False
                i += 1
            return True
        if isp(n) or isp(m):
            return -1
        INF = float('inf')
        dist = [INF] * N
        dist[n] = n
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist[v]:
                continue
            if v == m:
                return d
            s = str(v).zfill(L)
            for i in range(L):
                dg = int(s[i])
                for nd in (dg + 1, dg - 1):
                    if 0 <= nd <= 9:
                        t = s[:i] + str(nd) + s[i+1:]
                        u = int(t)
                        if isp(u):
                            continue
                        nd2 = d + u
                        if nd2 < dist[u]:
                            dist[u] = nd2
                            heapq.heappush(pq, (nd2, u))
        return -1

