def solve(n, A):
    NEG = float('-inf')
    bo, be = NEG, NEG  # best sum of alternating chain ending at odd / even index (1-based)
    for i in range(1, n+1):
        a = A[i-1]
        if i % 2 == 1:
            cand = a + max(0, be)
            bo = max(bo, cand)
        else:
            if bo > NEG:
                be = max(be, a + bo)
    res = 0 if n % 2 == 0 else NEG
    res = max(res, be if n % 2 == 0 else bo)
