def solve(N,W,blocks,queries):
    cols={}
    for i,(x,y) in enumerate(blocks):
        cols.setdefault(x,[]).append((y,i))
    rank=[0]*N
    K=10**18
    for x in range(1,W+1):
        lst=sorted(cols.get(x,[]))
        K=min(K,len(lst))
        for r,(y,i) in enumerate(lst,1): rank[i]=r
    if W==0: K=0
    f=[]
    prev=0
    for r in range(1,K+1):
        M=max(sorted(cols[x])[r-1][0] for x in range(1,W+1))
        cur=max(prev+1,M); f.append(cur); prev=cur
    out=[]
    for T,A in queries:
        r=rank[A-1]
        if r<=K and T>=f[r-1]: out.append("No")
        else: out.append("Yes")
    return out

