def brute(s):
    best=0
    t='1'+s+'1'
    n=len(t)
    # try all trades: choose ones-block surrounded by zeros, convert to zeros; then zero-block surrounded by ones, fill; or no trade
    def count(x): return x.count('1')
    best=count(s)
    # enumerate all contiguous segments of t consisting of 1s, bounded by 0 on both sides (within t)
    for i in range(n):
        for j in range(i,n):
            seg=t[i:j+1]
            if set(seg)!={'1'}: continue
            if i==0 or j==n-1: continue
            if t[i-1]!='0' or t[j+1]!='0': continue
            u=t[:i]+'0'*(j-i+1)+t[j+1:]
            for a in range(n):
                for b in range(a,n):
                    sg=u[a:b+1]
